/**
 * FROZEN CONTRACT: domain entities as services and screens see them (camelCase).
 * Database rows are snake_case and live in contracts/db-types.ts (generated by AI-1). Repositories map between them.
 * Ids are UUID strings. Timestamps are ISO 8601 strings in UTC. Money is integer kobo.
 */
import type {
  AuditResult,
  ContributionFrequency,
  Currency,
  Kobo,
  LedgerDirection,
  LedgerEntryType,
  MemberStatus,
  NotificationChannel,
  NotificationType,
  ObligationStatus,
  PaymentAttemptStatus,
  PaymentChannel,
  PaymentPurpose,
  PayoutStatus,
  PlanStatus,
  PolicyKind,
  PrivacyRequestKind,
  PrivacyRequestStatus,
  ReconciliationStatus,
  RefundStatus,
  Role,
  SecurityEventType,
  Severity,
  SupportTicketStatus,
} from "./enums";

export type Uuid = string;
export type IsoTimestamp = string;
/** Calendar date without time, YYYY-MM-DD, in the Africa/Lagos business calendar. */
export type IsoDate = string;

export interface Member {
  id: Uuid;
  email: string;
  phone: string | null;
  fullName: string;
  status: MemberStatus;
  roles: Role[];
  emailVerifiedAt: IsoTimestamp | null;
  createdAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
}

export interface ContributionPlan {
  id: Uuid;
  memberId: Uuid;
  frequency: ContributionFrequency;
  amountKobo: Kobo;
  currency: Currency;
  status: PlanStatus;
  /** First due date. Later due dates are computed from frequency. */
  startsOn: IsoDate;
  /** Preferred saved payment method for automatic collection, if the member chose one. */
  paymentMethodId: Uuid | null;
  createdAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
}

export interface ContributionObligation {
  id: Uuid;
  planId: Uuid;
  memberId: Uuid;
  dueOn: IsoDate;
  amountKobo: Kobo;
  currency: Currency;
  status: ObligationStatus;
  paidByAttemptId: Uuid | null;
  createdAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
}

export interface PaymentMethodRef {
  id: Uuid;
  memberId: Uuid;
  /** Provider authorization reference. Server side only. Never sent to the client. */
  providerAuthorizationRef: string;
  /** Provider card signature. Used to avoid saving the same card twice for one member. */
  providerCardSignature: string;
  brand: string | null;
  last4: string | null;
  expMonth: number | null;
  expYear: number | null;
  bank: string | null;
  reusable: boolean;
  /** Email used when the authorization was created. */
  authorizationEmail: string;
  createdAt: IsoTimestamp;
  revokedAt: IsoTimestamp | null;
}

/** Safe view of a saved method for screens. Contains no provider references. */
export interface PaymentMethodView {
  id: Uuid;
  brand: string | null;
  last4: string | null;
  expMonth: number | null;
  expYear: number | null;
  bank: string | null;
  reusable: boolean;
}

export interface PaymentAttempt {
  id: Uuid;
  memberId: Uuid;
  purpose: PaymentPurpose;
  channel: PaymentChannel | null;
  amountKobo: Kobo;
  currency: Currency;
  status: PaymentAttemptStatus;
  /** Unique reference sent to the provider. */
  reference: string;
  /** Client supplied key, unique per member, so a repeated tap is the same attempt. */
  idempotencyKey: string;
  obligationId: Uuid | null;
  paymentMethodId: Uuid | null;
  /** Provider transaction id once known. */
  providerTransactionId: string | null;
  failureCode: string | null;
  createdAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
  completedAt: IsoTimestamp | null;
}

export interface PaymentEvent {
  id: Uuid;
  provider: "paystack";
  /** Provider event id. Unique, so a duplicate webhook is a no-op. */
  providerEventId: string;
  eventType: string;
  /** Raw body exactly as received, stored before any processing. Contains no card data. */
  rawPayload: unknown;
  signatureValid: boolean;
  receivedAt: IsoTimestamp;
  processedAt: IsoTimestamp | null;
  processingError: string | null;
  attemptId: Uuid | null;
}

export interface LedgerEntry {
  id: Uuid;
  memberId: Uuid;
  entryType: LedgerEntryType;
  direction: LedgerDirection;
  /** Always positive. Direction says whether it adds or subtracts. */
  amountKobo: Kobo;
  currency: Currency;
  paymentAttemptId: Uuid | null;
  payoutId: Uuid | null;
  refundId: Uuid | null;
  /** Required for adjustments. */
  reason: string | null;
  /** Receipt number for contribution credits. Immutable. */
  receiptNumber: string | null;
  createdBy: Uuid | null;
  createdAt: IsoTimestamp;
}

export interface Balance {
  memberId: Uuid;
  currency: Currency;
  /** Sum of all ledger entries. */
  ledgerKobo: Kobo;
  /** Ledger balance minus money held by the open payout request. */
  availableKobo: Kobo;
  heldKobo: Kobo;
}

export interface PayoutRequest {
  id: Uuid;
  memberId: Uuid;
  amountKobo: Kobo;
  currency: Currency;
  status: PayoutStatus;
  /** Destination copied at request time so later profile edits cannot redirect an approved payout. */
  destinationBankCode: string;
  destinationBankName: string;
  destinationAccountNumber: string;
  destinationAccountName: string | null;
  verifiedAt: IsoTimestamp | null;
  decidedBy: Uuid | null;
  decidedAt: IsoTimestamp | null;
  decisionNote: string | null;
  providerTransferRef: string | null;
  requestedAt: IsoTimestamp;
  resolvedAt: IsoTimestamp | null;
}

export interface Refund {
  id: Uuid;
  paymentAttemptId: Uuid;
  memberId: Uuid;
  amountKobo: Kobo;
  currency: Currency;
  status: RefundStatus;
  reason: string;
  requestedBy: Uuid;
  decidedBy: Uuid | null;
  providerRefundRef: string | null;
  createdAt: IsoTimestamp;
  resolvedAt: IsoTimestamp | null;
}

export interface ReconciliationRecord {
  id: Uuid;
  runId: Uuid;
  paymentAttemptId: Uuid | null;
  providerReference: string | null;
  status: ReconciliationStatus;
  expectedKobo: Kobo | null;
  providerKobo: Kobo | null;
  note: string | null;
  createdAt: IsoTimestamp;
  resolvedAt: IsoTimestamp | null;
  resolvedBy: Uuid | null;
}

export interface Notification {
  id: Uuid;
  memberId: Uuid;
  type: NotificationType;
  channel: NotificationChannel;
  title: string;
  body: string;
  /** Deep link inside the app, for example /app/history/<id>. */
  link: string | null;
  readAt: IsoTimestamp | null;
  createdAt: IsoTimestamp;
}

export interface Announcement {
  id: Uuid;
  title: string;
  body: string;
  publishedAt: IsoTimestamp | null;
  createdBy: Uuid;
  createdAt: IsoTimestamp;
}

export interface SupportTicket {
  id: Uuid;
  memberId: Uuid;
  subject: string;
  status: SupportTicketStatus;
  createdAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
}

export interface SupportMessage {
  id: Uuid;
  ticketId: Uuid;
  authorId: Uuid;
  fromStaff: boolean;
  body: string;
  createdAt: IsoTimestamp;
}

export interface SecurityEvent {
  id: Uuid;
  type: SecurityEventType;
  severity: Severity;
  memberId: Uuid | null;
  ip: string | null;
  userAgent: string | null;
  requestId: string | null;
  detail: Record<string, unknown>;
  createdAt: IsoTimestamp;
}

export interface AuditLogEntry {
  id: Uuid;
  actorId: Uuid | null;
  action: string;
  targetType: string | null;
  targetId: string | null;
  result: AuditResult;
  ip: string | null;
  requestId: string | null;
  detail: Record<string, unknown>;
  createdAt: IsoTimestamp;
}

export interface PolicyVersion {
  id: Uuid;
  kind: PolicyKind;
  version: string;
  body: string;
  /** True until a qualified Nigerian legal review signs it off. */
  draft: boolean;
  publishedAt: IsoTimestamp | null;
}

export interface PolicyAcceptance {
  id: Uuid;
  memberId: Uuid;
  policyVersionId: Uuid;
  acceptedAt: IsoTimestamp;
  ip: string | null;
}

export interface PrivacyRequest {
  id: Uuid;
  memberId: Uuid;
  kind: PrivacyRequestKind;
  status: PrivacyRequestStatus;
  createdAt: IsoTimestamp;
  resolvedAt: IsoTimestamp | null;
}

/** Cursor based page. Never offset pagination on history, ledger, audit or notification lists. */
export interface Page<T> {
  items: T[];
  /** Opaque cursor for the next page, or null at the end. */
  nextCursor: string | null;
}

export interface PageRequest {
  limit: number;
  cursor?: string | null;
}
